x0, x1, y0, y1 = [float(v) for v in sys.argv[1:5]]
rows = []
for e in ms:
    t = e.dxftype()
    if t == 'LINE':
        a, b = e.dxf.start, e.dxf.end
        if x0 <= a.x <= x1 and y0 <= a.y <= y1 and x0 <= b.x <= x1 and y0 <= b.y <= y1:
            L = math.hypot(a.x - b.x, a.y - b.y)
            if L > 0.3 and e.dxf.color in (7, 1) :
                rows.append((round(a.x, 3), round(a.y, 3), round(b.x, 3), round(b.y, 3), round(L, 3), e.dxf.color, e.dxf.linetype))
    elif t in ('ARC', 'CIRCLE'):
        c = e.dxf.center
        if x0 <= c.x <= x1 and y0 <= c.y <= y1:
            rows.append((t, round(c.x, 3), round(c.y, 3), round(e.dxf.radius, 3), e.dxf.color, e.dxf.linetype))
rows.sort(key=lambda r: (str(r[0]),))
for r in rows:
    print(r)
print(len(rows))

