import sys, os, json
sys.path.insert(0, r'C:\Users\DELL\Desktop\AI_CAD\Create_Flatten_SheetMetal-main\tools\sheetmetal_kit')
import geom as G
import ezdxf
d = r'C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\27-11-2026\521127-10'
tmp = r'C:\Users\DELL\AppData\Local\Temp\ai_cad_521127-10'
doc = ezdxf.readfile(os.path.join(d, '521127-10_ALL.dxf'))
ms = doc.modelspace()
bands = {'26-072745': (-10, 200), '26-072619': (600, 800), '26-072747': (900, 1100), '26-072746': (1150, 1400)}


def ycen(e):
    t = e.dxftype()
    if t == 'LINE':
        return (e.dxf.start.y + e.dxf.end.y) / 2
    if t in ('ARC', 'CIRCLE'):
        return e.dxf.center.y
    if t == 'POINT':
        return e.dxf.location.y
    return None


def col(e):
    c = e.dxf.color
    return c if c in (1, 3) else None


groups = {k: [] for k in bands}
for e in ms:
    t = e.dxftype()
    if t == 'TEXT':
        continue
    y = ycen(e)
    for k, (a, b) in bands.items():
        if a <= y <= b:
            groups[k].append(e)
for k, es in groups.items():
    ents = []
    for e in es:
        t = e.dxftype()
        lt = e.dxf.linetype if e.dxf.hasattr('linetype') else 'BYLAYER'
        if t == 'LINE':
            ents.append(G.L((e.dxf.start.x, e.dxf.start.y), (e.dxf.end.x, e.dxf.end.y), dashed=(lt == 'DASHED'), color=col(e)))
        elif t == 'ARC':
            ents.append(G.A((e.dxf.center.x, e.dxf.center.y), e.dxf.radius, e.dxf.start_angle, e.dxf.end_angle, color=col(e)))
        elif t == 'CIRCLE':
            ents.append(G.C((e.dxf.center.x, e.dxf.center.y), e.dxf.radius * 2))
        elif t == 'POINT':
            ents.append(G.P((e.dxf.location.x, e.dxf.location.y), color=col(e)))
    x0, y0, x1, y1 = G.bbox(ents)
    ents2 = G.transform(ents, 0, False, -x0, -y0)
    w, h = x1 - x0, y1 - y0
    # entity ALL cu co the lech 0.0 nhe: giu nguyen
    G.save_spec(os.path.join(tmp, 'parts', 'spec_%s.json' % k), k, ents2, w, h, flags=[])
    print(k, len(ents2), 'shift', round(x0, 4), round(y0, 4), 'w,h', round(w, 3), round(h, 3), 'orig y0', round(y0, 3))

